	for(let i=0,n=arr.length;i<n-1;i++){
		let minIndex=i;
		for(let j=i+1;j<n;j++)
			if(arr[j]<arr[minIndex])
				minIndex=j;
		[arr[i],arr[minIndex]]=[arr[minIndex],arr[i]];
	}
	return arr;
}

const insertionSort = arr => {
	for(let i=1,n=arr.length;i<n;i++){
		let key=arr[i],j=i-1;
		while(j>=0&&arr[j]>key){
			arr[j+1]=arr[j];
			j--;
		}
		arr[j+1]=key;
	}
	return arr;
}

