const partition=(arr,low,high)=>{
	const pivot=arr[high];
	let i=low-1;
	for(let j=low;j<high;j++)
		if(arr[j]<pivot)
			[arr[i+1],arr[j]]=[arr[j],arr[i+1]],i++;
	[arr[i+1],arr[high]]=[arr[high],arr[i+1]];
	return i+1;
};

